'use client';
import {appPath} from '@/lib/app-path';
import React,{useState,useEffect,useRef} from 'react';
import {CalendarDays,ChartNoAxesCombined,Flame,Layers,Plus,ChevronLeft,ChevronRight,ChevronDown,ArrowUpRight,ArrowDownToLine,ArrowUpFromLine,Check,CheckCheck,Clock3,Target,TrendingUp,MoreHorizontal,Bell,Search,Settings2,X,Play,Pause,Square,Leaf,SlidersHorizontal,ExternalLink,CloudCheck,CloudOff,RefreshCw,PanelLeft,Trash2,Flag,Sun,Sparkles,BookOpen,BriefcaseBusiness,Dumbbell,House,CheckCircle2,Info,Repeat2} from 'lucide-react';
import {Journal,Task,Category,today,uid,asDate,addDays,weekStart,time,minutes,formatHours,emptyData,demoData,stats,range,streak,parseICS,toICS,download,validData} from './model';
import Projects from './projects';
import ReviewPanel from './review-panel';
import ReportPanel from './report-panel';
import {Project,normalizeData} from './model';
import {holidaySet,SOURCES} from './holidays';
const weekday=['周一','周二','周三','周四','周五','周六','周日'];
const monthLabel=(d:string)=>`${Number(d.slice(0,4))} 年 ${Number(d.slice(5,7))} 月`;
const dateLabel=(d:string)=>`${Number(d.slice(5,7))} 月 ${Number(d.slice(8))} 日`;
const shortDate=(d:string)=>`${Number(d.slice(5,7))}/${Number(d.slice(8))}`;
const iconFor=[BriefcaseBusiness,BookOpen,Dumbbell,House];
type Modal='task'|'import'|'settings'|'focus'|'category'|'backup'|'start'|'habit'|null;
type Timer={taskId:string;started:number;elapsed:number;running:boolean};
export default function Dashboard({initialDate,initialNow,userId,userName}:{initialDate:string;initialNow:number;userId:string;userName:string}){
  const [nowDate,setNowDate]=useState(initialDate),[date,setDate]=useState(initialDate),[data,setData]=useState<Journal>(()=>demoData(initialDate)),[demo,setDemo]=useState(true),[loaded,setLoaded]=useState(false);
  const [sync,setSync]=useState('loading'),[page,setPage]=useState('calendar'),[view,setView]=useState('week'),[period,setPeriod]=useState('week'),[selectedCats,setSelectedCats]=useState<string[]|null>(null),[status,setStatus]=useState('all'),[query,setQuery]=useState(''),[sidebar,setSidebar]=useState(false);
  const [modal,setModal]=useState<Modal>(null),[editing,setEditing]=useState<Task|null>(null),[toast,setToast]=useState(''),[timer,setTimer]=useState<Timer|null>(null),[tick,setTick]=useState(initialNow),[focusTask,setFocusTask]=useState(''),[permission,setPermission]=useState('default');
  const revision=useRef(0),queue=useRef(Promise.resolve()),fileRef=useRef<HTMLInputElement>(null),backupRef=useRef<HTMLInputElement>(null),notified=useRef(new Set<string>());
  const notify=(message:string)=>setToast(message);
  useEffect(()=>{let active=true;fetch(appPath('/api/state')).then(async r=>{if(!r.ok){setSync(r.status===401?'login':'error');return;}const p:any=await r.json();if(!active)return;revision.current=p.revision;if(p.data&&validData(p.data)){setData(normalizeData(p.data));setDemo(false);}setSync('synced');}).catch(()=>setSync('error')).finally(()=>setLoaded(true));if('Notification'in window)setPermission(Notification.permission);return()=>{active=false;};},[]);
  useEffect(()=>{try{const raw=localStorage.getItem('momentum-active-timer:'+userId);if(raw){const t=JSON.parse(raw);if(typeof t.taskId==='string'&&Number.isFinite(t.started)&&Number.isFinite(t.elapsed)&&typeof t.running==='boolean'&&t.elapsed>=0)setTimer(t);}}catch{}},[]);
  useEffect(()=>{if(!loaded)return;try{if(timer)localStorage.setItem('momentum-active-timer:'+userId,JSON.stringify(timer));else localStorage.removeItem('momentum-active-timer:'+userId);}catch{}},[timer,loaded]);
  useEffect(()=>{const close=(e:KeyboardEvent)=>{if(e.key==='Escape')setModal(null);};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close);},[]);
  useEffect(()=>{window.scrollTo({top:0});},[page]);
  useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t);},[toast]);
  useEffect(()=>{const t=setInterval(()=>{setTick(Date.now());setNowDate(today());},1000);return()=>clearInterval(t);},[]);
  useEffect(()=>{if(!loaded||demo)return;const check=()=>{for(const task of data.tasks){if(task.reminder<0||task.progress===100)continue;const due=new Date(task.date+'T00:00:00+08:00').getTime()+(task.start-task.reminder)*60000;const key=task.id+due;if(Date.now()>=due&&Date.now()-due<60000&&!notified.current.has(key)){notified.current.add(key);notify('即将开始：'+task.title);if('Notification'in window&&Notification.permission==='granted')new Notification('有序 · 行动提醒',{body:task.title+' · '+time(task.start),icon:appPath('/favicon.svg')});}}};check();const t=setInterval(check,20000);return()=>clearInterval(t);},[data,loaded,demo]);
  function persist(next:Journal){setSync('saving');queue.current=queue.current.then(async()=>{try{const r=await fetch(appPath('/api/state'),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:next,revision:revision.current})});const p:any=await r.json();if(!r.ok)throw new Error(p.error||'保存失败');revision.current=p.revision;setSync('synced');}catch(e){setSync('error');notify((e as Error).message+'；可在设置导出备份');throw e;}}).catch(()=>{});}
  function change(next:Journal){next=normalizeData(next);if(!validData(next)){notify('记录格式不正确或超过容量，请检查输入');return;}setData(next);if(!demo)persist(next);else notify('正在体验示例；点击「开始我的记录」保存自己的行动');}
  function begin(){const next=emptyData();setData(next);setDemo(false);setTimer(null);persist(next);setModal(null);notify('新的开始，从一个小小的行动开始吧。');}
  function openTask(d=date,start=540,task:Task|null=null,event=false){setEditing(task||{id:uid(),title:'',date:d,start,end:Math.min(start+60,1440),category:data.categories[0]?.id||'career',progress:0,actual:0,note:'',reminder:10,event});setModal('task');}
  function saveTask(task:Task,repeat:string){let base=data;const tasks=base.tasks.filter(t=>t.id!==task.id);tasks.push(task);if(repeat!=='none'){for(let i=1;i<=(repeat==='daily'?6:3);i++)tasks.push({...task,id:uid(),date:addDays(task.date,i*(repeat==='daily'?1:7)),progress:0,actual:0});}const next={...base,tasks};if(!validData(next)){notify('记录格式不正确，请检查任务关联和日期');return;}change(next);setModal(null);if(!demo)notify(repeat==='none'?'时间块已保存':'时间块与后续安排已保存');}
  async function logout(){if(!demo&&sync!=='synced'&&!confirm('记录尚未同步，建议先导出备份。仍要退出吗？'))return;await queue.current;const r=await fetch(appPath('/api/session'),{method:'DELETE',credentials:'same-origin'});if(r.ok)window.location.assign(appPath('/login'));else notify('暂时无法退出，请重试');}
  const filter=(t:Task)=> (selectedCats===null||selectedCats.includes(t.category))&&(!query||t.title.toLowerCase().includes(query.toLowerCase()))&&(status==='all'||(status==='done'?t.progress===100:t.progress<100));
  const visibleTasks=data.tasks.filter(filter),week=weekStart(date),days=Array.from({length:7},(_,i)=>addDays(week,i));
  const statTasks=data.tasks.filter(t=>selectedCats===null||selectedCats.includes(t.category));
  const [start,end]=range(date,period),currentTasks=statTasks.filter(t=>t.date>=start&&t.date<=end),summary=stats(currentTasks,data.categories),dayStats=stats(statTasks.filter(t=>t.date===date),data.categories);
  const statSeries=Array.from({length:7},(_,i)=>stats(statTasks.filter(t=>t.date===addDays(week,i)),data.categories));
  const weekSummary=stats(statTasks.filter(t=>t.date>=week&&t.date<=addDays(week,6)),data.categories);
  const elapsed=timer?timer.elapsed+(timer.running?Math.max(0,Math.floor((tick-timer.started)/1000)):0):0;
  const catFor=(id:string)=>data.categories.find(c=>c.id===id)||data.categories[0];
  function finishTimer(){if(!timer)return;const mins=Math.round(elapsed/60);if(!mins){setTimer(null);notify('本次专注不足 30 秒，未计入时长');return;}const next={...data,tasks:data.tasks.map(t=>t.id===timer.taskId?{...t,actual:Math.min(1440,t.actual+mins)}:t)};change(next);setTimer(null);notify(`已记录 ${mins} 分钟专注，每一点投入都有价值。`);}
  function navigate(direction:number){if(page==='calendar'&&view==='month'){const d=asDate(date);d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+direction);setDate(d.toISOString().slice(0,10));}else setDate(addDays(date,direction*(page==='calendar'&&view==='day'?1:7)));}
  function complete(t:Task){change({...data,tasks:data.tasks.map(x=>x.id===t.id?{...x,progress:x.progress===100?0:100}:x)});if(t.progress<100)notify('又完成了一件事，给自己的行动一个肯定。');}
  function toggleHabit(id:string,d=nowDate){change({...data,habits:data.habits.map(h=>h.id===id?{...h,days:h.days.includes(d)?h.days.filter(x=>x!==d):[...h.days,d]}:h)});}
  const focusCandidates=data.tasks.filter(t=>t.date===nowDate&&!t.event&&t.progress<100);
  const upcoming=data.tasks.filter(t=>t.event&&t.date>=nowDate&&filter(t)).sort((a,b)=>(a.date+time(a.start)).localeCompare(b.date+time(b.start)));
  const syncText=demo?'示例空间':sync==='saving'?'正在保存…':sync==='synced'?'云端已同步':sync==='login'?'登录以同步':'同步失败 · 点击重试';
  const title=page==='projects'?'产品与成果':page==='reports'?'成长报告':page==='calendar'?'执行日历':page==='analytics'?'统计回顾':page==='habits'?'习惯养成':'未来事件';
  return <div className="app-shell">
    <aside className={'sidebar '+(sidebar?'mobile-open':'')}>
      <a className="brand" href="#" onClick={e=>{e.preventDefault();setPage('calendar');}}><span className="brand-mark"><i/><i/><i/></span><span>有序<span className="brand-en">MOMENTUM</span></span></a>
      <div className="workspace"><span className="workspace-icon">M</span><div>我的成长空间<small>Make a little progress, daily.</small></div><ChevronDown size={15}/></div>
      <div className="nav-caption">工作空间</div>
      <nav>{[['calendar','执行日历',CalendarDays],['projects','产品与成果',BriefcaseBusiness],['reports','成长报告',BookOpen],['analytics','统计回顾',ChartNoAxesCombined],['habits','习惯养成',Flame],['events','未来事件',Flag]].map(([key,label,Icon]:any)=><button key={key} className={'nav-item '+(page===key?'active':'')} onClick={()=>{setPage(key);setSidebar(false);}}><Icon size={19}/><span>{label}</span>{key==='events'&&upcoming.length>0&&<b>{upcoming.length}</b>}</button>)}</nav>
      <div className="nav-caption category-caption">我的分类<button className="icon-button" aria-label="管理分类" onClick={()=>setModal('category')}><Plus size={15}/></button></div>
      <div className="category-list">{data.categories.map((c,i)=>{const Icon=iconFor[i]||Layers;const active=selectedCats===null||selectedCats.includes(c.id);return <button key={c.id} className={!active?'muted-category':''} onClick={()=>setSelectedCats(active?(selectedCats||data.categories.map(x=>x.id)).filter(x=>x!==c.id):[...(selectedCats||[]),c.id])}><span className="category-square" style={{background:c.color+'19',color:c.color}}>{active?<Check size={12}/>:<Icon size={12}/>}</span>{c.name}{c.focus&&<span className="focus-dot" title="计入正事专注"/>}</button>;})}</div>
      {selectedCats!==null&&<button className="text-button reset-filter" onClick={()=>setSelectedCats(null)}>重置分类筛选</button>}
      <button className="sidebar-import" onClick={()=>setModal('import')}><ArrowDownToLine size={17}/>导入日历与节假日<Plus size={14}/></button>
      <div className="sidebar-bottom"><div className="growth-note"><span className="seed-icon"><Leaf size={21}/></span><strong>慢慢来，也是在向前。</strong><p>把微小的坚持，变成看得见的成长。</p><div className="sprout-art"><i/><i/><span/></div></div><button className="settings-nav" onClick={()=>setModal('settings')}><Settings2 size={18}/>偏好与数据设置</button><div className="profile"><span>M</span><div>{userName}<small>保持行动，自有答案</small></div><span className="profile-dot"/></div></div>
    </aside>
    {sidebar&&<div className="sidebar-scrim" onClick={()=>setSidebar(false)}/>}
    <div className="main-wrap"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" aria-label="打开导航" onClick={()=>setSidebar(true)}><PanelLeft size={20}/></button><span>我的成长空间</span><ChevronRight size={13}/><strong>{title}</strong></div><div className="topbar-actions"><button className={'sync-state '+(sync==='error'?'sync-error':'')} onClick={()=>{if(!demo&&sync==='error')persist(data);else if(sync==='login')window.location.href=appPath('/login');}}>{demo?<span className="demo-dot"/>:sync==='synced'?<CloudCheck size={14}/>:<CloudOff size={14}/>}<span>{syncText}</span></button><span className="topbar-separator"/><button className="icon-button" aria-label="提醒设置" onClick={()=>setModal('settings')}><Bell size={18}/><span className="notification-dot"/></button><button className="icon-button" onClick={logout} aria-label="退出登录" title="退出登录"><ExternalLink size={18}/></button><span className="avatar" title={userName}>{userName.slice(0,1).toUpperCase()}</span></div></header>
    <main>
      <section className="page-heading"><div><div className="eyebrow"><Sun size={15}/> 每一天，都有新的可能</div><h1>{page==='projects'?'让投入，成为看得见的成果。':page==='reports'?'回看走过的路，继续向前。':page==='calendar'?'把时间，留给重要的事。':page==='analytics'?'看见投入，也看见成长。':page==='habits'?'好的状态，从小事开始。':'为值得期待的事，留出时间。'}</h1><p>{page==='projects'?'连接每天的行动，记录长期任务的每一次推进。':page==='reports'?'周报、月报、年报，让积累成为下一步的方向。':page==='calendar'?'规划你的行动，记录每一次专注。让进步有迹可循。':page==='analytics'?'让时间的去向清晰，让每一点积累都有回响。':page==='habits'?'不追求完美的一天，只收集持续行动的每一天。':'提前安排，安心投入。把未来变成今天的方向。'}</p></div>{!['projects','reports'].includes(page)&&<div className="heading-actions"><button className="button secondary focus-entry" onClick={()=>{setFocusTask(focusCandidates[0]?.id||'');setModal('focus');}}><Play size={14}/>专注</button><button className="button secondary" onClick={()=>setModal('import')}><ArrowDownToLine size={15}/>导入日历</button><button className="button primary" onClick={()=>openTask(date,540,null,page==='events')}><Plus size={17}/>{page==='events'?'新建事件':'新建时间块'}</button></div>}</section>
      {demo&&<div className="demo-banner"><span><Sparkles size={15}/><strong>先看看，理想的一周是什么样。</strong><span>当前展示示例数据，你的记录从这里开始。</span></span><button onClick={()=>setModal('start')} disabled={!loaded}>开始我的记录 <ArrowUpRight size={14}/></button></div>}
      {!['projects','reports'].includes(page)&&<><div className="stats-top"><div className="overview-label"><span className="section-dot"/>{page==='analytics'?{day:'每日',week:'每周',month:'每月',year:'每年'}[period]:'本周'}概览 <span className="overview-dates">{shortDate(page==='analytics'?start:week)} — {shortDate(page==='analytics'?end:addDays(week,6))}</span></div>{page==='analytics'&&<><input className="analytics-date" aria-label="统计日期" type="date" value={date} onChange={e=>{if(e.target.value)setDate(e.target.value);}}/><div className="segmented">{[['day','日'],['week','周'],['month','月'],['year','年']].map(([id,label])=><button className={period===id?'selected':''} key={id} onClick={()=>setPeriod(id)}>{label}</button>)}</div></>}<button className="text-button" onClick={()=>{setPage(page==='analytics'?'calendar':'analytics');}}> {page==='analytics'?'回到日历':'查看统计'} <ArrowUpRight size={14}/></button></div>
      <div className="stat-cards"><Stat series={statSeries.map(s=>s.rate)} title="计划完成率" icon={<CheckCheck size={18}/>} value={(page==='analytics'?summary:weekSummary).rate} suffix="%" detail={`${(page==='analytics'?summary:weekSummary).done} / ${(page==='analytics'?summary:weekSummary).total} 个时间块已完成`} spark="rate"/><Stat series={statSeries.map(s=>s.focus)} title="正事专注时长" icon={<Target size={18}/>} value={formatHours((page==='analytics'?summary:weekSummary).focus)} suffix="小时" detail="将时间投资于真正重要的事" spark="focus"/><Stat series={Array.from({length:7},(_,i)=>streak(data,addDays(week,i)))} title="连续行动" icon={<Flame size={18}/>} value={streak(data,nowDate)} suffix="天" detail={streak(data,nowDate)>0?'持续行动，就是你的超能力':'今天，就是最好的开始'} spark="streak"/><Stat series={statSeries.map(s=>s.actual)} title="实际投入时长" icon={<Clock3 size={18}/>} value={formatHours((page==='analytics'?summary:weekSummary).actual)} suffix="小时" detail={`计划 ${(formatHours((page==='analytics'?summary:weekSummary).plan))} 小时 · 每一步都算数`} spark="time"/></div>
      </>}
      {page==='projects'&&<Projects data={data} onChange={change} notify={notify} onTask={t=>openTask(t.date,t.start,t)} onSchedule={p=>{setEditing({id:uid(),title:p.name,date:date<p.startDate?p.startDate:date,start:540,end:600,category:p.category,progress:0,actual:0,note:'',reminder:10,projectId:p.id});setModal('task');}}/>}
      {page==='reports'&&<ReportPanel data={data} demo={demo}/>}
      {page==='calendar'&&<div className="calendar-layout"><section className="calendar-card"><div className="calendar-toolbar"><div className="calendar-date"><label className="calendar-month-label"><h2>{monthLabel(date)}</h2><input type="date" aria-label="跳转日期" value={date} onChange={e=>{if(e.target.value)setDate(e.target.value);}}/></label><div className="date-arrows"><button className="icon-button" aria-label="上一段时间" onClick={()=>navigate(-1)}><ChevronLeft size={16}/></button><button className="icon-button" aria-label="下一段时间" onClick={()=>navigate(1)}><ChevronRight size={16}/></button></div><button className="today-button" onClick={()=>setDate(nowDate)}>今天</button></div><div className="calendar-tools"><div className="segmented">{[['day','日'],['week','周'],['month','月']].map(([id,label])=><button key={id} className={view===id?'selected':''} onClick={()=>setView(id)}>{label}</button>)}</div><button className={'icon-button '+(status!=='all'?'filter-on':'')} aria-label="筛选完成状态" title={status==='all'?'显示全部':status==='open'?'未完成':'已完成'} onClick={()=>setStatus(status==='all'?'open':status==='open'?'done':'all')}><SlidersHorizontal size={17}/></button></div></div>
      <div className="calendar-subbar"><span><span className="little-dot"/>点击空白处，安排一个小行动</span><div><span>香港时间 GMT+8</span>{status!=='all'&&<button onClick={()=>setStatus('all')}>{status==='open'?'未完成':'已完成'} <X size={11}/></button>}</div></div>
      {view==='month'?<MonthCalendar date={date} tasks={visibleTasks} holidays={data.holidays} nowDate={nowDate} catFor={catFor} onDay={(d:string)=>{setDate(d);setView('day');}} onTask={(t:Task)=>openTask(t.date,t.start,t)}/>:<TimeCalendar now={tick} days={view==='day'?[date]:days} nowDate={nowDate} selectedDate={date} tasks={visibleTasks} holidays={data.holidays} catFor={catFor} onDay={setDate} onAdd={openTask} onTask={(t:Task)=>openTask(t.date,t.start,t)} onComplete={complete}/>}
      <div className="calendar-footer"><div>{data.categories.map(c=><span key={c.id}><i style={{background:c.color}}/>{c.name}</span>)}</div><span>{visibleTasks.filter(t=>(view==='day'?t.date===date:t.date>=week&&t.date<=addDays(week,6))).length} 个时间块</span></div>
      </section><aside className="right-rail"><section className="daily-card"><div className="card-label"><h3>{date===nowDate?'今日行动':'当日行动'}</h3><span>{dateLabel(date)}</span></div><div className="progress-ring" style={{'--progress':dayStats.rate+'%'} as React.CSSProperties}><div><strong>{dayStats.rate}<small>%</small></strong><span>今日完成度</span></div><svg width="164" height="164" viewBox="0 0 164 164"><circle cx="82" cy="82" r="68" fill="none" stroke="#edf0e9" strokeWidth="9"/><circle cx="82" cy="82" r="68" fill="none" stroke="#6f9771" strokeWidth="9" strokeLinecap="round" strokeDasharray={`${dayStats.rate*4.2726} 427.26`} transform="rotate(-90 82 82)"/></svg></div><div className="daily-numbers"><div><strong>{dayStats.done}<small> / {dayStats.total}</small></strong><span>完成时间块</span></div><div><strong>{formatHours(dayStats.focus)}<small> h</small></strong><span>正事专注</span></div></div><div className="focus-goal"><span>每日专注目标</span><b>{formatHours(dayStats.focus)} / {formatHours(data.goal)} h</b><div><i style={{width:Math.min(100,dayStats.focus/data.goal*100)+'%'}}/></div></div><button className="button primary focus-button" onClick={()=>{setFocusTask(focusCandidates[0]?.id||'');setModal('focus');}}><Play size={14} fill="currentColor"/>{timer?'回到专注':'开始一段专注'}</button><div className="encouragement"><Leaf size={13}/>{dayStats.rate>=80?'今天的你，已经做得很好了。':'专注一件事，就是很好的开始。'}</div></section>
      <section className="habit-card"><div className="card-label"><h3>小习惯，大改变 <span className="tiny-leaf">✦</span></h3><button className="icon-button" aria-label="查看全部习惯" onClick={()=>setPage('habits')}><ArrowUpRight size={15}/></button></div><p>把好状态，慢慢养成日常</p>{data.habits.slice(0,3).map(h=><button className={'habit-row '+(h.days.includes(nowDate)?'checked':'')} onClick={()=>toggleHabit(h.id)} key={h.id}><span className="habit-check">{h.days.includes(nowDate)&&<Check size={12}/>}</span><span>{h.title}</span><span className="habit-days">{h.days.filter(d=>d>=addDays(nowDate,-6)&&d<=nowDate).length}/7</span></button>)}</section>
      <section className="upcoming-card"><div className="card-label"><h3>即将到来</h3><button className="text-button" onClick={()=>setPage('events')}>全部 <ChevronRight size={13}/></button></div>{upcoming.length?upcoming.slice(0,2).map(t=><button className="upcoming-item" onClick={()=>openTask(t.date,t.start,t)} key={t.id}><span className="date-tile"><small>{Number(t.date.slice(5,7))}月</small><b>{Number(t.date.slice(8))}</b></span><span><strong>{t.title}</strong><small><Clock3 size={11}/>{time(t.start)}{t.reminder>=0&&<Bell size={11}/>}</small></span></button>):<button className="empty-upcoming" onClick={()=>openTask(nowDate,540,null,true)}><Plus size={16}/>安排一件值得期待的事</button>}</section></aside></div>}
      {page==='calendar'&&<ReviewPanel key={date} data={data} date={date} onChange={change}/>}
      {(page==='analytics'||page==='calendar')&&<div className={'insights-grid '+(page==='calendar'?'below-calendar':'')}><TrendChart data={{...data,tasks:statTasks}} date={date} period={page==='analytics'?period:'week'}/><CategoryChart tasks={page==='analytics'?currentTasks:statTasks.filter(t=>t.date>=week&&t.date<=addDays(week,6))} categories={data.categories}/></div>}
      {page==='analytics'&&<><section className="panel heatmap-panel"><div className="panel-heading"><div><h3>每一次行动，都留下了痕迹</h3><p>过去 12 周 · 颜色越深，正事专注越久</p></div><span className="heatmap-legend">少 {[0,1,2,3,4].map(n=><i key={n} className={'heat-'+n}/>)} 多</span></div><div className="heatmap">{Array.from({length:84},(_,i)=>{const d=addDays(nowDate,i-83);const s=stats(data.tasks.filter(t=>t.date===d),data.categories);return <button key={d} title={`${d} · ${formatHours(s.focus)} 小时`} className={'heat-'+Math.min(4,Math.ceil(s.focus/90))} onClick={()=>{setDate(d);setPeriod('day');}}/>;})}</div></section><section className="panel formula-note"><Info size={16}/><div><strong>让数字有意义</strong><p>完成率 = Σ（计划时长 × 进度）÷ 总计划时长。专注时长来自计时或手动填写的实际分钟，仅统计标记为「正事」的分类；未来事件不计入完成率与时长。无计划的时段显示 0%。所有日期按香港时间记录。</p></div></section></>}
      {page==='habits'&&<section className="panel habits-page"><div className="panel-heading"><div><h3>我的习惯清单</h3><p>点击日期打卡，也可以补记。积累比连续更重要。</p></div><button className="button secondary" onClick={()=>setModal('habit')}><Plus size={15}/>新建习惯</button></div><div className="habit-table"><div className="habit-table-head"><span>这一周的小坚持</span>{days.map((d,i)=><span className={d===nowDate?'today-text':''} key={d}>{weekday[i]}<small>{shortDate(d)}</small></span>)}<span>累计</span></div>{data.habits.map(h=><div className="habit-table-row" key={h.id}><span><Leaf size={17}/>{h.title}<button className="icon-button" aria-label={'删除习惯'+h.title} onClick={()=>{if(confirm('删除这个习惯和它的打卡记录？'))change({...data,habits:data.habits.filter(x=>x.id!==h.id)});}}><Trash2 size={13}/></button></span>{days.map(d=><span key={d}><button disabled={d>nowDate} className={'habit-day '+(h.days.includes(d)?'done':'')} aria-label={`${h.title} ${d} ${h.days.includes(d)?'已打卡':'打卡'}`} onClick={()=>toggleHabit(h.id,d)}>{h.days.includes(d)?<Check size={16}/>:<Plus size={13}/>}</button></span>)}<strong>{h.days.length}<small> 天</small></strong></div>)}</div><div className="habits-nav"><button className="button secondary" onClick={()=>setDate(addDays(date,-7))}><ChevronLeft size={14}/>上一周</button><span>{shortDate(week)} — {shortDate(addDays(week,6))}</span><button className="button secondary" onClick={()=>setDate(addDays(date,7))}>下一周<ChevronRight size={14}/></button></div></section>}
      {page==='events'&&<section className="panel events-page"><div className="panel-heading"><div><h3>未来事件</h3><p>香港时间 · 提前安排，把期待放进日历</p></div><label className="search-input"><Search size={15}/><input placeholder="搜索事件…" value={query} onChange={e=>setQuery(e.target.value)}/></label></div><div className="event-list">{upcoming.length?upcoming.map(t=><div className="event-row" key={t.id}><span className="date-tile"><small>{Number(t.date.slice(5,7))}月</small><b>{Number(t.date.slice(8))}</b></span><div><strong>{t.title}</strong><p>{t.date} · {time(t.start)} — {time(t.end)} <span style={{color:catFor(t.category)?.color}}> / {catFor(t.category)?.name}</span></p></div><span className="reminder-tag"><Bell size={13}/>{t.reminder>=0?`提前 ${t.reminder} 分钟`:'无提醒'}</span><button className="icon-button" aria-label={'导出事件'+t.title} onClick={()=>download(t.title+'.ics',toICS([t]),'text/calendar')}><ArrowUpFromLine size={17}/></button><button className="button secondary" onClick={()=>openTask(t.date,t.start,t)}>编辑</button></div>):<div className="empty-state"><CalendarDays size={38}/><h3>给未来留一点期待</h3><p>新建一个事件，或导入你的 .ics 日历。</p><button className="button primary" onClick={()=>openTask(nowDate,540,null,true)}><Plus size={15}/>新建事件</button></div>}</div><div className="notification-info"><Bell size={16}/>网页提醒需要保持页面打开。导出事件到手机或电脑日历后，由系统日历负责闹钟提醒。</div></section>}
      <footer className="page-footer"><span className="footer-logo"><Leaf size={13}/> 有序 MOMENTUM · v2.1</span><span>不必每天都完美，只要每天都向前一点。</span><button onClick={()=>setModal('backup')}>导出我的记录 <ArrowUpFromLine size={12}/></button></footer>
    </main></div>
    {timer&&<div className="floating-timer"><span className={'timer-pulse '+(timer.running?'running':'')}/><div><small>{data.tasks.find(t=>t.id===timer.taskId)?.title}</small><strong>{Math.floor(elapsed/60).toString().padStart(2,'0')}:{(elapsed%60).toString().padStart(2,'0')}</strong></div><button className="icon-button" aria-label={timer.running?'暂停专注':'继续专注'} onClick={()=>setTimer({...timer,running:!timer.running,elapsed,started:Date.now()})}>{timer.running?<Pause size={18}/>:<Play size={18}/>}</button><button className="timer-stop" aria-label="结束并记录专注" onClick={finishTimer}><Square size={14} fill="currentColor"/>结束</button></div>}
    {toast&&<div className="toast" role="status"><CheckCircle2 size={17}/>{toast}<button className="icon-button" aria-label="关闭提示" onClick={()=>setToast('')}><X size={14}/></button></div>}
    {modal&&<div className="modal-overlay" onClick={e=>{if(e.target===e.currentTarget)setModal(null);}}><section className={'modal '+(modal==='task'?'task-modal':'')} role="dialog" aria-modal="true" aria-labelledby="modal-title"><button className="modal-close icon-button" aria-label="关闭弹窗" onClick={()=>setModal(null)}><X size={20}/></button>
    {modal==='task'&&editing&&<TaskForm projects={data.projects||[]} task={editing} categories={data.categories} existing={data.tasks.some(t=>t.id===editing.id)} onSave={saveTask} onDelete={()=>{change({...data,tasks:data.tasks.filter(t=>t.id!==editing.id)});setModal(null);}} onExport={t=>download(t.title+'.ics',toICS([t]),'text/calendar')}/>}
    {modal==='start'&&<><div className="modal-symbol"><Leaf size={28}/></div><h2 id="modal-title">从今天开始，积累自己的成长</h2><p className="modal-description">收起示例，建立你的个人行动日历。时间块、专注记录和习惯打卡会保存到云端。</p><div className="modal-info">每天的一小步，会成为未来很大的一步。</div><button className="button primary full" onClick={begin}>开启我的记录 <ArrowUpRight size={15}/></button></>}
    {modal==='import'&&<ImportPanel data={data} demo={demo} onChange={(next:Journal)=>{if(demo){const real={...emptyData(),holidays:next.holidays};setData(real);setDemo(false);persist(real);}else change(next);}} onImportTasks={(tasks:Task[])=>{const base=demo?{...emptyData(),categories:data.categories,goal:data.goal}:data;const ids=new Set(base.tasks.map(t=>t.id));const unique=tasks.filter(t=>{if(ids.has(t.id))return false;ids.add(t.id);return true;});const next={...base,tasks:[...base.tasks,...unique]};setData(next);if(demo)setDemo(false);persist(next);notify(`已导入 ${unique.length} 个事件，重复项自动跳过`);}} notify={notify} fileRef={fileRef}/>}
    {modal==='focus'&&<><div className="modal-symbol"><Target size={28}/></div><h2 id="modal-title">留一段时间，专注当下</h2><p className="modal-description">选择今天的行动，实际投入会计入它的专注时长。完成进度由你自己记录。</p>{timer?<><div className="focus-timer-display">{Math.floor(elapsed/60).toString().padStart(2,'0')}:{(elapsed%60).toString().padStart(2,'0')}</div><p className="centered">{data.tasks.find(t=>t.id===timer.taskId)?.title}</p><button className="button primary full" onClick={()=>{finishTimer();setModal(null);}}>结束并记录这次专注</button></>:focusCandidates.length?<><label className="field">今天专注哪件事？<select value={focusTask} onChange={e=>setFocusTask(e.target.value)}>{focusCandidates.map(t=><option value={t.id} key={t.id}>{time(t.start)} · {t.title}</option>)}</select></label><button className="button primary full" onClick={()=>{setTimer({taskId:focusTask||focusCandidates[0].id,started:Date.now(),elapsed:0,running:true});setModal(null);}}><Play size={15}/>开始专注</button></>:<><div className="modal-info">今天还没有未完成的时间块，先安排一件重要的事吧。</div><button className="button primary full" onClick={()=>openTask(nowDate)}>创建今天的行动</button></>}</>}
    {modal==='settings'&&<><div className="modal-eyebrow">MAKE IT YOURS</div><h2 id="modal-title">让有序，更适合你</h2><p className="modal-description">好工具应该配合你的节奏。</p><label className="field">每日正事专注目标<select value={data.goal} onChange={e=>change({...data,goal:Number(e.target.value)})}>{[60,120,180,240,300,360,480].map(n=><option value={n} key={n}>{n/60} 小时 / 天</option>)}</select></label><div className="settings-section"><h3><Bell size={17}/>网页提醒</h3><p>页面打开时提醒你即将开始的行动。关闭页面后的闹钟，请将事件导出到系统日历。</p><button className="button secondary" onClick={async()=>{if(!('Notification'in window)){notify('当前浏览器不支持通知，请导出到系统日历');return;}const p=await Notification.requestPermission();setPermission(p);notify(p==='granted'?'已开启网页通知':'通知未开启，请在浏览器设置中允许');}}>{permission==='granted'?<Check size={15}/>:<Bell size={15}/>} {permission==='granted'?'已开启通知':'开启浏览器通知'}</button></div><div className="settings-section"><h3><Layers size={17}/>分类与专注统计</h3><p>事业成长、学习提升默认计入正事专注。你可以自行调整分类。</p><button className="button secondary" onClick={()=>setModal('category')}>管理任务分类</button></div><div className="settings-section"><h3><CloudCheck size={17}/>我的数据</h3><p>{demo?'目前为示例数据。开始我的记录后，内容会保存到个人云端。':sync==='synced'?'个人记录已同步到云端，登录同一账号即可继续使用。':'记录尚未成功同步，请重试或先导出备份。'}</p><div className="button-row"><button className="button secondary" onClick={()=>setModal('backup')}>备份与导出</button>{!demo&&sync==='error'&&<button className="button secondary" onClick={()=>persist(data)}><RefreshCw size={14}/>重试同步</button>}{sync==='login'&&<a className="button primary" href={appPath('/login')} target="_top">登录以保存记录</a>}</div></div><div className="settings-footnote">时区固定为 Asia/Hong_Kong（UTC+8），与中国大陆时间一致。</div></>}
    {modal==='category'&&<CategoryPanel data={data} change={change}/>}
    {modal==='habit'&&<form onSubmit={e=>{e.preventDefault();const form=new FormData(e.currentTarget);const title=String(form.get('title')||'').trim();if(!title)return;change({...data,habits:[...data.habits,{id:uid(),title,days:[]}]});setModal(null);}}><div className="modal-symbol"><Flame size={27}/></div><h2 id="modal-title">种下一个小习惯</h2><p className="modal-description">从简单到可以每天做到的一件事开始。</p><label className="field">习惯名称<input autoFocus required maxLength={100} name="title" placeholder="例如：睡前阅读 20 分钟"/></label><button className="button primary full" type="submit">开始积累</button></form>}
    {modal==='backup'&&<><div className="modal-eyebrow">YOUR DATA, YOUR PROGRESS</div><h2 id="modal-title">把每一次行动，好好保存</h2><p className="modal-description">完整备份可以在这里恢复；日历文件可以导入 Apple 日历、Google 日历等，接收系统提醒。</p><div className="export-options"><button onClick={()=>download('有序-完整备份-'+nowDate+'.json',JSON.stringify(data,null,2))}><Layers size={22}/><span><strong>导出完整备份</strong><small>JSON · 时间块、习惯、分类与节假日</small></span><ArrowUpFromLine size={17}/></button><button onClick={()=>download('有序-日历-'+nowDate+'.ics',toICS(data.tasks),'text/calendar')}><CalendarDays size={22}/><span><strong>导出日历与提醒</strong><small>ICS · 含已设定的事件闹钟</small></span><ArrowUpFromLine size={17}/></button><button onClick={()=>backupRef.current?.click()}><ArrowDownToLine size={22}/><span><strong>恢复完整备份</strong><small>导入 JSON · 将替换当前全部记录</small></span><ChevronRight size={17}/></button></div><input hidden ref={backupRef} type="file" accept=".json" onChange={async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>1500000)throw new Error('文件太大');const next=JSON.parse(await f.text());if(!validData(next))throw new Error('文件格式不正确');if(!confirm('恢复备份将替换当前记录。建议先导出当前备份，确认继续？'))return;const restored=normalizeData(next);setData(restored);setDemo(false);setTimer(null);persist(restored);setModal(null);notify('备份已恢复');}catch(err){notify('无法恢复：'+(err as Error).message);}e.target.value='';}}/><div className="modal-info">日历闹钟的最终送达取决于系统日历的导入和通知设置。</div></>}
    </section></div>}
  </div>;
}
function Stat({title,icon,value,suffix,detail,spark,series}:{title:string;icon:React.ReactNode;value:number|string;suffix:string;detail:string;spark:string;series:number[]}){const max=Math.max(1,...series);const path=series.map((v,i)=>(i?'L':'M')+(2+i*13)+','+(34-v/max*29)).join(' ');return <section className={'stat-card stat-'+spark}><div className="stat-label">{title}<span>{icon}</span></div><div className="stat-value">{value}<small>{suffix}</small><svg className="sparkline" width="82" height="38" viewBox="0 0 82 38" aria-hidden="true"><path d={path} fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg></div><p>{detail}</p></section>;}
function TimeCalendar({days,now,nowDate,selectedDate,tasks,holidays,catFor,onDay,onAdd,onTask,onComplete}:any){
 const all=tasks.filter((t:Task)=>days.includes(t.date)),first=Math.min(8,...all.map((t:Task)=>Math.floor(t.start/60))),last=Math.max(20,...all.map((t:Task)=>Math.ceil(t.end/60))),height=56,hours=Array.from({length:last-first},(_,i)=>first+i);
 const current=new Date(now+8*3600000),m=current.getUTCHours()*60+current.getUTCMinutes();
 return <div className={'time-calendar '+(days.length===1?'single-day':'')}><div className="week-heading" style={{gridTemplateColumns:`48px repeat(${days.length},minmax(0,1fr))`}}><div className="timezone-corner">GMT+8</div>{days.map((d:string)=>{const h=holidays.filter((x:any)=>x.date===d);const day=(asDate(d).getUTCDay()+6)%7;return <button onClick={()=>onDay(d)} className={'day-heading '+(d===nowDate?'is-today':'')+(d===selectedDate?' is-selected':'')+(day>4?' weekend':'')} key={d}><span>{weekday[day]}</span><strong>{Number(d.slice(8))}</strong>{h.length>0?<small className={h[0].work?'work-holiday':'holiday'} title={h.map((x:any)=>x.name+' · '+(x.region==='HK'?'香港':'大陆')).join('\n')}>{h[0].work?'班':h[0].name}</small>:<small>{d===nowDate?'TODAY':'\u00a0'}</small>}</button>;})}</div><div className="calendar-scroll"><div className="time-grid" style={{gridTemplateColumns:`48px repeat(${days.length},minmax(0,1fr))`,height:hours.length*height}}><div className="time-axis">{hours.map(h=><span style={{top:(h-first)*height}} key={h}>{String(h).padStart(2,'0')}:00</span>)}</div>{days.map((d:string)=>{const dayTasks=tasks.filter((t:Task)=>t.date===d).sort((a:Task,b:Task)=>a.start-b.start);const groups:Task[][]=[];for(const t of dayTasks){const g=groups.find(g=>g.some(x=>x.start<t.end&&x.end>t.start));if(g)g.push(t);else groups.push([t]);}return <div key={d} className={'day-column '+(d===nowDate?'today-column':'')} style={{height:hours.length*height}}>{hours.map(h=><button className="hour-slot" key={h} aria-label={`${d} ${h}:00 新建时间块`} style={{top:(h-first)*height,height}} onClick={()=>onAdd(d,h*60)}><Plus size={14}/></button>)}{dayTasks.map((t:Task)=>{const c=catFor(t.category),group=groups.find(g=>g.includes(t))!,index=group.indexOf(t),cols=group.length;return <div key={t.id} className={'time-block '+(t.progress===100?'completed':'')+(t.event?' event-block':'')} style={{top:(t.start/60-first)*height+3,height:Math.max(26,(t.end-t.start)/60*height-6),background:c?.color+'17',borderLeftColor:c?.color,color:c?.color,left:`calc(${index/cols*100}% + 4px)`,width:`calc(${100/cols}% - 8px)`}}><button className="time-block-content" onClick={()=>onTask(t)} title={`${t.title} · ${time(t.start)}–${time(t.end)} · ${t.progress}%`}><span className="block-time">{time(t.start)} – {time(t.end)}{t.reminder>=0&&<Bell size={9}/>}</span><strong>{t.title}</strong>{t.end-t.start>=60&&<div className="block-bottom"><span>{t.event?'未来事件':t.progress===100?'已完成':t.progress>0?`进行中 ${t.progress}%`:'待开始'}</span>{!t.event&&<i><b style={{width:t.progress+'%',background:c?.color}}/></i>}</div>}</button>{!t.event&&<button className="block-complete" aria-label={(t.progress===100?'取消完成':'完成')+t.title} onClick={()=>onComplete(t)}>{t.progress===100?<CheckCircle2 size={12}/>:<span/>}</button>}</div>;})}{d===nowDate&&m>=first*60&&m<last*60&&<div className="now-line" style={{top:(m/60-first)*height}}><i/></div>}</div>;})}</div></div></div>;
}
function MonthCalendar({date,tasks,holidays,nowDate,catFor,onDay,onTask}:any){const first=date.slice(0,7)+'-01',start=weekStart(first);const days=Array.from({length:42},(_,i)=>addDays(start,i));return <div className="month-calendar"><div className="month-weekdays">{weekday.map(x=><span key={x}>{x}</span>)}</div><div className="month-grid">{days.map(d=>{const ts=tasks.filter((t:Task)=>t.date===d),hs=holidays.filter((h:any)=>h.date===d);return <div key={d} className={'month-cell '+(d.slice(0,7)!==date.slice(0,7)?'outside':'')}><button className={'month-day '+(d===nowDate?'today':'')} onClick={()=>onDay(d)}>{Number(d.slice(8))}</button>{hs.length>0&&<span className="month-holiday" title={hs.map((h:any)=>h.name).join('、')}>{hs[0].name}</span>}{ts.slice(0,3).map((t:Task)=><button className="month-task" key={t.id} style={{color:catFor(t.category)?.color,background:catFor(t.category)?.color+'14'}} onClick={()=>onTask(t)}>{t.progress===100&&<Check size={10}/>}<span>{time(t.start)} {t.title}</span></button>)}{ts.length>3&&<button className="more-tasks" onClick={()=>onDay(d)}>还有 {ts.length-3} 项</button>}<button className="month-add" onClick={()=>onDay(d)} aria-label={'查看'+d}><Plus size={14}/></button></div>;})}</div></div>;}
function TrendChart({data,date,period}:{data:Journal,date:string,period:string}){const [s,e]=range(date,period);let points:{label:string,start:string,end:string}[]=[];if(period==='year')points=Array.from({length:12},(_,i)=>{const st=date.slice(0,4)+'-'+String(i+1).padStart(2,'0')+'-01';return{label:(i+1)+'月',start:st,end:range(st,'month')[1]};});else if(period==='month'){for(let d=s;d<=e;d=addDays(d,7))points.push({label:shortDate(d),start:d,end:addDays(d,6)>e?e:addDays(d,6)});}else if(period==='day'){points=Array.from({length:12},(_,i)=>({label:`${i*2}:00`,start:s,end:s}));}else points=Array.from({length:7},(_,i)=>({label:weekday[i],start:addDays(s,i),end:addDays(s,i)}));const values=points.map((p,i)=>stats(data.tasks.filter(t=>t.date>=p.start&&t.date<=p.end&&(period!=='day'||(t.start>=i*120&&t.start<(i+1)*120))),data.categories).focus/60);const max=Math.max(period==='year'?20:6,...values.map(v=>Math.ceil(v)));const x=(i:number)=>48+i*(590/(points.length-1||1)),y=(v:number)=>145-v/max*120;const path=values.map((v,i)=>(i?'L':'M')+x(i)+','+y(v)).join(' ');return <section className="panel trend-panel"><div className="panel-heading"><div><h3>专注，让成长发生 <TrendingUp size={16}/></h3><p>正事专注时长 · {period==='day'?'每 2 小时':period==='month'?'按周':period==='year'?'按月':'每天'}</p></div><span className="chart-key"><i/>实际专注</span></div><svg className="trend-chart" viewBox="0 0 665 188" role="img" aria-label={'专注时长趋势 '+points.map((p,i)=>p.label+values[i].toFixed(1)+'小时').join('，')}><defs><linearGradient id="chart-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#709970" stopOpacity=".19"/><stop offset="100%" stopColor="#709970" stopOpacity="0"/></linearGradient></defs>{[0,1,2,3].map(n=>{const v=max*n/3;return <g key={n}><line x1="48" x2="638" y1={y(v)} y2={y(v)} stroke="#edf0eb" strokeDasharray="3 4"/><text x="4" y={y(v)+4} fill="#a3a89e" fontSize="10">{Number(v.toFixed(1))}h</text></g>;})}<path d={path+` L${x(values.length-1)},145 L48,145 Z`} fill="url(#chart-fill)"/><path d={path} fill="none" stroke="#6c9271" strokeWidth="2.5" strokeLinejoin="round"/>{values.map((v,i)=><g key={i}><circle cx={x(i)} cy={y(v)} r="4" fill="white" stroke="#6c9271" strokeWidth="2"><title>{`${points[i].label} · ${v.toFixed(1)} 小时`}</title></circle><text x={x(i)} y="178" textAnchor="middle" fill="#93988e" fontSize="10">{points[i].label}</text></g>)}</svg></section>;}
function CategoryChart({tasks,categories}:{tasks:Task[],categories:Category[]}){const total=tasks.filter(t=>!t.event).reduce((s,t)=>s+t.actual,0);return <section className="panel category-chart"><div className="panel-heading"><div><h3>时间，花在哪里？</h3><p>当前统计周期 · 实际投入分布</p></div><Clock3 size={16}/></div><div className="stacked-bar">{categories.map(c=>{const n=tasks.filter(t=>!t.event&&t.category===c.id).reduce((s,t)=>s+t.actual,0);return <i key={c.id} title={c.name+' '+formatHours(n)+' 小时'} style={{background:c.color,width:total?n/total*100+'%':'0%'}}/>;})}{total===0&&<span>记录一段投入，让时间有迹可循</span>}</div><div className="category-breakdown">{categories.map(c=>{const n=tasks.filter(t=>!t.event&&t.category===c.id).reduce((s,t)=>s+t.actual,0);return <div key={c.id}><span><i style={{background:c.color}}/>{c.name}{c.focus&&<small>正事</small>}</span><b>{formatHours(n)} <small>h</small></b></div>;})}</div></section>;}
function TaskForm({task,categories,projects,existing,onSave,onDelete,onExport}:{task:Task;categories:Category[];projects:Project[];existing:boolean;onSave:(t:Task,r:string)=>void;onDelete:()=>void;onExport:(t:Task)=>void}){const[t,setT]=useState(task),[repeat,setRepeat]=useState('none'),[error,setError]=useState('');const update=(k:string,v:any)=>setT({...t,[k]:v});return <form onSubmit={e=>{e.preventDefault();if(t.end<=t.start){setError('结束时间需要晚于开始时间');return;}if(!t.title.trim())return;const linked=projects.find(p=>p.id===t.projectId);if(linked&&t.date<linked.startDate){setError('日程日期不能早于关联任务的初始日期');return;}onSave({...t,title:t.title.trim()},repeat);}}><div className="modal-eyebrow">A LITTLE ACTION, A LITTLE PROGRESS</div><h2 id="modal-title">{existing?'记录这一步的进展':t.event?'留一件值得期待的事':'为重要的事，留一段时间'}</h2><div className="type-toggle segmented"><button type="button" className={!t.event?'selected':''} onClick={()=>update('event',false)}><Layers size={14}/>行动时间块</button><button type="button" className={t.event?'selected':''} onClick={()=>setT({...t,event:true,projectId:undefined})}><Flag size={14}/>未来事件</button></div>{!t.event&&<label className="field">关联产品 / 长期任务<select value={t.projectId||''} onChange={e=>{const p=projects.find(p=>p.id===e.target.value);setT({...t,projectId:p?.id,title:t.title||p?.name||'',category:p?.category||t.category});}}><option value="">不关联任务</option>{projects.filter(p=>!p.endDate||p.id===t.projectId).map(p=><option key={p.id} value={p.id}>{p.name}{p.endDate?'（已完成，保留关联）':''}</option>)}</select><small>实际投入和进展将汇总到所选任务；仅可新关联未结束的任务。</small></label>}<label className="field">{t.event?'事件名称':'要做什么？'}<input autoFocus value={t.title} required maxLength={200} placeholder="例如：用 90 分钟推进核心项目" onChange={e=>update('title',e.target.value)}/></label><div className="form-grid"><label className="field">日期<input type="date" required value={t.date} onChange={e=>update('date',e.target.value)}/></label><label className="field">任务分类<select value={t.category} onChange={e=>update('category',e.target.value)}>{categories.map(c=><option value={c.id} key={c.id}>{c.name}{c.focus?' · 正事':''}</option>)}</select></label><label className="field">开始时间<input type="time" required value={time(t.start)} onChange={e=>update('start',minutes(e.target.value))}/></label><label className="field">结束时间{t.end===1440?<select value="1440" onChange={()=>update('end',1380)}><option value="1440">24:00（次日零点）</option><option value="1380">23:00</option></select>:<input type="time" required value={time(t.end)} onChange={e=>update('end',minutes(e.target.value))}/>}</label></div><div className="duration-pills"><span>计划 {(Math.max(0,t.end-t.start)/60).toFixed(1)} 小时</span>{[60,90,120].map(n=><button type="button" key={n} className={t.end-t.start===n?'active':''} onClick={()=>update('end',Math.min(1440,t.start+n))}>{n===60?'1 小时':n===90?'1.5 小时':'2 小时'}</button>)}</div>{!t.event&&<><label className="field progress-field"><span>完成进度 <b>{t.progress}%</b></span><input type="range" min="0" max="100" step="5" value={t.progress} onChange={e=>update('progress',Number(e.target.value))}/><div className="range-labels"><span>尚未开始</span><button type="button" onClick={()=>update('progress',100)}><Check size={12}/>标为完成</button></div></label><label className="field">实际投入（分钟）<input type="number" value={t.actual} min="0" max="1440" step="1" required onChange={e=>update('actual',Number(e.target.value))}/><small>可手动补记，也可以使用专注计时器。完成进度与投入时长分别记录。</small></label></>}<div className="form-grid"><label className="field">提前提醒<select value={t.reminder} onChange={e=>update('reminder',Number(e.target.value))}>{[[-1,'不提醒'],[0,'开始时'],[5,'5 分钟'],[10,'10 分钟'],[15,'15 分钟'],[30,'30 分钟'],[60,'1 小时'],[1440,'1 天']].map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label>{!existing&&<label className="field">重复安排<select value={repeat} onChange={e=>setRepeat(e.target.value)}><option value="none">不重复</option><option value="daily">每天 · 共 7 天</option><option value="weekly">每周 · 共 4 周</option></select></label>}</div><label className="field">进展与想法 <span className="optional">选填</span><textarea rows={2} maxLength={4000} value={t.note} placeholder="今天推进了什么？下一步从哪里开始？" onChange={e=>update('note',e.target.value)}/></label>{error&&<div className="form-error">{error}</div>}<div className="form-actions">{existing?<button type="button" className="icon-button delete-button" aria-label="删除记录" onClick={()=>{if(confirm('确定删除这个时间块？'))onDelete();}}><Trash2 size={18}/></button>:<span/>}{existing&&<button type="button" className="button secondary" onClick={()=>onExport(t)}><ArrowUpFromLine size={14}/>导出提醒</button>}<button type="submit" className="button primary"><Check size={16}/>保存{t.event?'事件':'时间块'}</button></div></form>;}
function ImportPanel({data,demo,onChange,onImportTasks,notify,fileRef}:any){const[region,setRegion]=useState('HK'),[year,setYear]=useState(2026);const set=holidaySet(region,year);return <><div className="modal-eyebrow">PLAN AHEAD, LIVE PRESENT</div><h2 id="modal-title">让安排，自然连接</h2><p className="modal-description">把节假日和未来事件放进来，为重要的事提前留白。</p><div className="import-section"><h3><CalendarDays size={18}/>导入地区节假日</h3><div className="region-cards">{[['HK','香港','公众假期'],['CN','中国大陆','法定节假日与调休']].map(([id,name,desc])=><button key={id} className={region===id?'selected':''} onClick={()=>setRegion(id)}><span>{id==='HK'?'港':'中'}</span><strong>{name}</strong><small>{desc}</small>{region===id&&<CheckCircle2 size={16}/>}</button>)}</div><div className="holiday-import-row"><label>年份 <select value={year} onChange={e=>setYear(Number(e.target.value))}><option value="2026">2026 年</option><option value="2027">2027 年</option></select></label><button disabled={!set.length} className="button primary" onClick={()=>{const existing=data.holidays.filter((h:any)=>!(h.region===region&&h.date.startsWith(String(year))));onChange({...data,holidays:[...existing,...set]});notify(`已导入 ${year} 年${region==='HK'?'香港公众假期':'大陆节假日与补班'}，共 ${set.length} 天`);}}>导入到日历 <ArrowDownToLine size={14}/></button></div><p className="import-footnote">{set.length?`包含 ${set.length} 个标记日，重复导入会更新同年同地区数据。`:'2027 年大陆放假调休安排待官方公布。'}{demo&&' 当前为示例空间。'}</p><a className="source-link" href={SOURCES[region as 'HK'|'CN']} target="_blank" rel="noreferrer">查看官方数据来源 <ExternalLink size={11}/></a><p className="import-footnote">香港采用具名公众假期，星期日由周末样式显示。</p></div><div className="import-section"><h3><ArrowDownToLine size={18}/>从日历文件导入事件</h3><button className="file-drop" onClick={()=>fileRef.current?.click()}><span><ArrowDownToLine size={23}/></span><strong>选择 .ics 日历文件</strong><small>支持 Apple 日历、Google 日历、Outlook 导出文件</small></button><input hidden type="file" accept=".ics,text/calendar" ref={fileRef} onChange={async(e:any)=>{const f=e.target.files?.[0];if(!f)return;if(f.size>1000000){notify('请选择小于 1 MB 的日历文件');return;}try{const result=parseICS(await f.text(),data.categories[0].id);if(result.tasks.length>3000){notify('单次最多导入 3000 个事件');return;}if(result.tasks.length)onImportTasks(result.tasks);else notify('没有找到可导入的事件');if(result.skipped)notify(`导入 ${result.tasks.length} 个事件；${result.skipped} 个重复规则、跨日或不支持时区的事件未导入`);}catch{notify('读取失败，请检查日历文件格式');}e.target.value='';}}/><p className="import-footnote">支持 UTC、香港和上海时区；未注明时区按香港时间处理。全天事件安排到 09:00–10:00；重复规则和跨日事件暂不展开。相同 UID 自动去重。</p></div></>;}
function CategoryPanel({data,change}:{data:Journal;change:(d:Journal)=>void}){const[name,setName]=useState(''),[color,setColor]=useState('#50836a'),[focus,setFocus]=useState(false);return <><div className="modal-eyebrow">MAKE SPACE FOR WHAT MATTERS</div><h2 id="modal-title">给行动，找到归属</h2><p className="modal-description">开启「正事」的分类，其实际投入将计入正事专注统计。</p><div className="category-manager">{data.categories.map(c=><div key={c.id}><i style={{background:c.color}}/><input aria-label="分类名称" maxLength={40} value={c.name} onChange={e=>change({...data,categories:data.categories.map(x=>x.id===c.id?{...x,name:e.target.value}:x)})}/><button className={'focus-toggle '+(c.focus?'on':'')} onClick={()=>change({...data,categories:data.categories.map(x=>x.id===c.id?{...x,focus:!x.focus}:x)})}><Target size={12}/>{c.focus?'正事':'日常'}</button><button className="icon-button" aria-label={'删除分类'+c.name} disabled={(data.projects||[]).some(p=>p.category===c.id)||data.tasks.some(t=>t.category===c.id)||data.categories.length===1} title="有记录的分类需先迁移记录才可删除" onClick={()=>change({...data,categories:data.categories.filter(x=>x.id!==c.id)})}><Trash2 size={14}/></button></div>)}</div><form className="add-category" onSubmit={e=>{e.preventDefault();if(!name.trim())return;change({...data,categories:[...data.categories,{id:uid(),name:name.trim(),color,focus}]});setName('');}}><h3>新建分类</h3><div className="category-add-fields"><input type="color" aria-label="分类颜色" value={color} onChange={e=>setColor(e.target.value)}/><input placeholder="分类名称" required maxLength={40} value={name} onChange={e=>setName(e.target.value)}/></div><label className="checkbox-label"><input type="checkbox" checked={focus} onChange={e=>setFocus(e.target.checked)}/>计入正事专注</label><button disabled={data.categories.length>=30} className="button primary full" type="submit"><Plus size={15}/>添加分类</button></form></>;}
